"use client";
/* eslint-disable @next/next/no-img-element -- QR is an ephemeral data URL generated by the trusted backend. */
import {FormEvent,useState} from "react";import {useRouter}from"next/navigation";import{completeAdminMFA,login}from"@/services/admin-api";
export function AdminLoginForm(){const router=useRouter();const[error,setError]=useState(""),[challenge,setChallenge]=useState(""),[setup,setSetup]=useState<{qr?:string;secret?:string}|null>(null),[recovery,setRecovery]=useState<string[]>([]),[loading,setLoading]=useState(false);const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(loading)return;setLoading(true);setError("");const form=new FormData(e.currentTarget);try{if(!challenge){const data=await login(String(form.get("email")),String(form.get("password")));setChallenge(data.challenge_token);if(data.action==="mfa_setup_required")setSetup({qr:data.qr_code_data_url,secret:data.setup_secret})}else{const data=await completeAdminMFA(challenge,String(form.get("code")||""),String(form.get("recovery_code")||""));sessionStorage.setItem("loja3d_admin_csrf",data.csrf_token);if(data.recovery_codes?.length){setRecovery(data.recovery_codes);return}router.push("/admin");router.refresh()}}catch(cause){setError(cause instanceof Error?cause.message:"Acesso negado.")}finally{setLoading(false)}};if(recovery.length)return <section className="admin-login-card"><span className="admin-kicker">Códigos de recuperação</span><h1>Guarde agora</h1><p>Eles não serão exibidos novamente.</p><pre className="admin-recovery">{recovery.join("\n")}</pre><button onClick={()=>{router.push("/admin");router.refresh()}}>Concluir</button></section>;return <form className="admin-login-card" onSubmit={submit}><span className="admin-kicker">Acesso restrito</span><h1>{challenge?setup?"Ativar MFA":"Segundo fator":"Operação Loja 3D"}</h1>{!challenge?<><p>Cloudflare Access e autenticação interna continuam obrigatórios.</p><label>E-mail<input name="email" type="email" autoComplete="username" required/></label><label>Senha<input name="password" type="password" autoComplete="current-password" minLength={12} required/></label></>:<>{setup?.qr&&<img className="admin-qr" src={setup.qr} alt="QR Code para configurar o autenticador"/>}{setup?.secret&&<p>Chave manual: <code>{setup.secret}</code></p>}<label>Código do autenticador<input name="code" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6}/></label>{!setup&&<label>Código de recuperação<input name="recovery_code" autoComplete="off"/></label>}</>}{error&&<div className="admin-alert" role="alert">{error}</div>}<button disabled={loading}>{loading?"Verificando…":challenge?"Confirmar fator":"Continuar"}</button></form>}
